#!/usr/bin/env node
/**
 * check-component-states.mjs — Auditoria estática da máquina de estados
 *
 * Fecha (parcialmente) o gap C.5 do PRD: o manual exige "8 estados" mas nada
 * verificava. Esta é uma checagem ESTÁTICA e HEURÍSTICA — pega os casos de
 * alta confiança, sem prometer cobrir tudo (estados de CSS como hover/focus
 * não são detectáveis aqui de forma confiável).
 *
 * O que detecta (alta confiança):
 *  - Ação ASSÍNCRONA (async + @click/@submit) sem nenhum sinal de loading/
 *    disabled → botão "quebrado" durante o request (Doherty Threshold).
 *  - Campo de formulário (DsInput/<input> com v-model) sem tratamento de erro.
 *
 * Por design é ADVISORY: exit 0 com avisos. Use --strict para falhar o CI.
 *
 * Uso:
 *   node scripts/check-component-states.mjs [--dir src] [--strict]
 *   npm run validate:states
 */

import { readFileSync, readdirSync, statSync, existsSync } from 'fs';
import { join, relative } from 'path';

const CWD = process.cwd();
const strict = process.argv.includes('--strict');
const dirArg = process.argv.indexOf('--dir');
const SRC = join(CWD, dirArg >= 0 && process.argv[dirArg + 1] ? process.argv[dirArg + 1] : 'src');

function collectVue(dir, acc = []) {
  if (!existsSync(dir)) return acc;
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry);
    const st = statSync(full);
    if (st.isDirectory() && entry !== 'node_modules' && entry !== '__tests__') collectVue(full, acc);
    else if (entry.endsWith('.vue')) acc.push(full);
  }
  return acc;
}

// Sinais (regex) de cada estado, em todo o SFC (template + script).
const SIGNALS = {
  async: /\basync\b|\bawait\b|\.then\(/,
  action: /@click|@submit|type=["']submit["']|<button|DsButton|DsIconButton|DsFormSubmit/i,
  loadingOrDisabled: /\bloading\b|\bisLoading\b|\bsubmitting\b|aria-busy|:disabled|\bdisabled\b|\bpending\b/i,
  formField: /<input|DsInput|DsSelect|DsTextarea|DsCurrencyInput|DsOTPInput/i,
  errorState: /\berror\b|aria-invalid|:error|\berrors\b/i,
};

const findings = [];

for (const file of collectVue(SRC)) {
  const src = readFileSync(file, 'utf-8');
  const rel = relative(CWD, file);
  const has = (k) => SIGNALS[k].test(src);

  // 1. Ação assíncrona sem feedback de loading/disabled (alta confiança)
  if (has('async') && has('action') && !has('loadingOrDisabled')) {
    findings.push({
      file: rel,
      level: 'warn',
      msg: 'Ação assíncrona sem estado de loading/disabled. Botão "trava" durante o request (Doherty). Adicione :disabled + aria-busy + loading.',
    });
  }

  // 2. Campo de formulário sem estado de erro (média confiança)
  if (has('formField') && !has('errorState')) {
    findings.push({
      file: rel,
      level: 'info',
      msg: 'Campo de formulário sem estado de erro visível. Inputs precisam de empty/focus/filled/error/disabled.',
    });
  }
}

console.log('═'.repeat(60));
console.log('  🔎 Auditoria de Estados de Componente (estática/heurística)');
console.log('═'.repeat(60));

if (findings.length === 0) {
  console.log('\n✅ Nenhuma ausência de estado de alta confiança detectada.\n');
  process.exit(0);
}

const warns = findings.filter((f) => f.level === 'warn');
const infos = findings.filter((f) => f.level === 'info');

for (const f of findings) {
  console.log(`\n  ${f.level === 'warn' ? '⚠️ ' : 'ℹ️ '} ${f.file}`);
  console.log(`      ${f.msg}`);
}

console.log('\n' + '─'.repeat(60));
console.log(`  ${warns.length} avisos, ${infos.length} infos (heurístico — confirme manualmente)`);
console.log('─'.repeat(60) + '\n');

// Advisory por padrão; --strict falha o build se houver avisos.
process.exit(strict && warns.length > 0 ? 1 : 0);
